const extracted = $('Data Extraction Agent').item.json.output;
const rules = {
  recommendation_levels: {
    Ready: "No major issue prevents release and remaining risks are acceptable",
    Conditional: "Release may proceed only after specific actions, approvals, or risk acceptance",
    "Not Ready": "Important issues must be resolved before release"
  },
  defect_severity_rules: {
    Critical: "Release should not proceed until the defect is resolved",
    High: "Release normally should not proceed unless there is formal approval and a strong business reason",
    Medium: "Release may proceed if business impact is understood, a workaround exists where needed, and the risk is accepted",
    Low: "Release may normally proceed if the issue is documented"
  },
  qa_rules: {
    critical_fail: "Release is Not Ready",
    high_priority_fail: "Release requires investigation before approval",
    medium_priority_fail: "Assess business impact and available workaround",
    low_priority_fail: "Document the issue and assess whether it can be accepted",
    regression_fail: "Review carefully because existing functionality may be affected",
    security_fail: "Release should not proceed until the issue is reviewed and resolved"
  },
  approval_rules: [
    "The AI system may assess release readiness but cannot approve a production release.",
    "The Technical Lead must make the final release decision.",
    "Any unresolved Critical or High-severity defect must be clearly highlighted.",
    "Medium-severity defects must include their business impact and any available workaround.",
    "Known issues accepted for release must be included in the final release report.",
    "The system must not hide or minimize failed tests simply because most tests passed.",
    "If release information is incomplete, conflicting, or uncertain, the system should clearly identify the uncertainty and request human review."
  ]
};

return [{
  json: {
    release_overview: extracted.release_overview,
    changes: extracted.changes,
    qa_results: extracted.qa_results,
    defects: extracted.defects,
    release_rules: rules
  }
}];

const raw = $('Report Generation Agent').item.json.output;

const isSepRow = (line) => {
  if (!/^\s*\|.*\|\s*$/.test(line)) return false;
  const cells = line.split('|').map(c => c.trim()).filter(c => c.length);
  return cells.length > 0 && cells.every(c => /^:?-+:?$/.test(c));
};

const mdToHtml = (t) => {
  let lines = t.split('\n');
  let out = [];
  let i = 0;
  while (i < lines.length) {
    let line = lines[i];

    if (/^\s*\|.*\|\s*$/.test(line) && lines[i+1] && isSepRow(lines[i+1])) {
      let headerCells = line.split('|').map(c => c.trim()).filter(c => c.length);
      let rows = [];
      i += 2;
      while (i < lines.length && /^\s*\|.*\|\s*$/.test(lines[i])) {
        rows.push(lines[i].split('|').map(c => c.trim()).filter(c => c.length));
        i++;
      }
      let thead = '<tr>' + headerCells.map(h => '<th style="border:1px solid #d0d5dd;padding:8px 10px;background:#0b2545;color:#ffffff;text-align:left;font-size:13px;">' + h + '</th>').join('') + '</tr>';
      let tbody = rows.map((r, idx) => '<tr style="background:' + (idx % 2 ? '#f4f6f8' : '#ffffff') + ';">' + r.map(c => '<td style="border:1px solid #d0d5dd;padding:8px 10px;font-size:13px;">' + c + '</td>').join('') + '</tr>').join('');
      out.push('<table style="border-collapse:collapse;width:100%;margin:14px 0;">' + thead + tbody + '</table>');
      continue;
    }

    out.push(line);
    i++;
  }
  let h = out.join('\n');
  h = h.replace(/^### (.*)$/gm, '<h4 style="color:#0b2545;margin:18px 0 6px;">$1</h4>');
  h = h.replace(/^## (.*)$/gm, '<h3 style="color:#0b2545;border-bottom:2px solid #e2e8f0;padding-bottom:4px;margin:22px 0 8px;">$1</h3>');
  h = h.replace(/^# (.*)$/gm, '<h2 style="color:#0b2545;margin:24px 0 10px;">$1</h2>');
  h = h.replace(/\*\*(.*?)\*\*/g, '<strong>$1</strong>');
  h = h.replace(/\*(.*?)\*/g, '<em>$1</em>');
  h = h.replace(/^- (.*)$/gm, '<li>$1</li>');
  h = h.replace(/(<li>.*<\/li>\n?)+/g, (m) => '<ul style="margin:8px 0;padding-left:22px;">' + m + '</ul>');
  h = h.split(/\n{2,}/).map(block => {
    if (/^<(h2|h3|h4|ul|li|table)/.test(block.trim())) return block;
    return '<p style="margin:8px 0;line-height:1.5;">' + block.replace(/\n/g, '<br>') + '</p>';
  }).join('');
  return h;
};

const escalation = $json.cycle_count >= 3
  ? '<div style="background:#fff4e5;border-left:4px solid #d97706;padding:10px 14px;margin-bottom:16px;font-size:13px;"><strong>Note:</strong> This item reached the maximum of 3 review cycles and is being escalated for manual follow-up, regardless of the last decision.</div>'
  : '';

// FULL detailed report -> goes into the PDF attachment only
const pdfBodyHtml = '<div style="font-family:Arial,Helvetica,sans-serif;max-width:720px;margin:0 auto;color:#1a1a1a;">' +
  '<div style="background:#0b2545;color:#ffffff;padding:20px 24px;">' +
    '<div style="font-size:12px;letter-spacing:1px;opacity:0.8;">NEXTWAVE SOFTWARE</div>' +
    '<div style="font-size:20px;font-weight:bold;margin-top:4px;">Release Readiness Notification</div>' +
  '</div>' +
  '<div style="padding:24px;border:1px solid #e2e8f0;border-top:none;">' +
    escalation +
    '<p style="font-size:14px;"><strong>Release Decision:</strong> ' + $json.data.Decision + '</p>' +
    '<p style="font-size:14px;"><strong>Technical Lead Comments:</strong><br>' + ($json.data.Comments || 'None provided') + '</p>' +
    '<hr style="border:none;border-top:1px solid #e2e8f0;margin:20px 0;">' +
    mdToHtml(raw) +
  '</div>' +
  '<div style="padding:14px 24px;font-size:11px;color:#667085;">This is an automated notification from the NextWave Release Readiness system. This assessment is advisory only — the Technical Lead retains final release authority.</div>' +
'</div>';

const pdfHtmlString = '<!DOCTYPE html><html><head><meta charset="utf-8"></head><body>' + pdfBodyHtml + '</body></html>';

// SHORT summary -> goes into the email body only
const shortSummary = $('Compliance & Recommendation Agent').item.json.output.summary || 'Please see the attached PDF for the full assessment.';

const emailHtmlString = '<div style="font-family:Arial,Helvetica,sans-serif;max-width:720px;margin:0 auto;color:#1a1a1a;">' +
  '<div style="background:#0b2545;color:#ffffff;padding:20px 24px;">' +
    '<div style="font-size:12px;letter-spacing:1px;opacity:0.8;">NEXTWAVE SOFTWARE</div>' +
    '<div style="font-size:20px;font-weight:bold;margin-top:4px;">Release Readiness Notification</div>' +
  '</div>' +
  '<div style="padding:24px;border:1px solid #e2e8f0;border-top:none;">' +
    escalation +
    '<p style="font-size:14px;"><strong>Release Decision:</strong> ' + $json.data.Decision + '</p>' +
    '<p style="font-size:14px;"><strong>Technical Lead Comments:</strong><br>' + ($json.data.Comments || 'None provided') + '</p>' +
    '<hr style="border:none;border-top:1px solid #e2e8f0;margin:20px 0;">' +
    '<p style="font-size:14px;line-height:1.6;">' + shortSummary + '</p>' +
    '<p style="font-size:13px;color:#475569;margin-top:20px;">📎 The full Release Readiness Report — including QA results, open defects, and risk assessment — is attached as a PDF to this email.</p>' +
  '</div>' +
  '<div style="padding:14px 24px;font-size:11px;color:#667085;">This is an automated notification from the NextWave Release Readiness system. This assessment is advisory only — the Technical Lead retains final release authority.</div>' +
'</div>';

return [{ json: { html: emailHtmlString, pdfHtml: pdfHtmlString, decision: $json.data.Decision, comments: $json.data.Comments } }];
